const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs');
(async()=>{const b=await chromium.launch();const p=await b.newPage();await p.goto('http://127.0.0.1:4181/admin/login?ui=classic');await p.locator('input[type=email]').fill('admin@dracula-design.com');await p.locator('input[type=password]').fill(process.env.QA_PASSWORD);await p.locator('[data-testid=login-submit]').click();await p.waitForTimeout(800);await p.goto('http://127.0.0.1:4181/admin/products?ui=classic');await p.waitForTimeout(1700);console.log('IMAGES',await p.locator('img').evaluateAll(imgs=>imgs.map(i=>({src:i.getAttribute('src'),loaded:i.naturalWidth>0}))));
await p.goto('http://127.0.0.1:4181/ro/');await p.waitForSelector('.shop-footer');const links=await p.locator('.shop-footer [data-link]').evaluateAll(a=>a.map(x=>x.href));for(const link of links){await p.goto(link);await p.waitForSelector('.legal-body');if((await p.locator('.legal-body').textContent()).length<60)throw Error('Empty page '+link);}console.log('LEGAL PAGES',links.length,'rendered');
const other=await b.newContext();const request=other.request;await request.get('http://127.0.0.1:4183/api/dracula/bootstrap');const cookie=(await other.cookies()).find(c=>c.name==='dracula_food_csrf');const r=await request.post('http://127.0.0.1:4183/api/account/login',{headers:{'X-CSRF-Token':cookie.value},data:{email:'client@dracula-design.com',password:process.env.QA_PASSWORD}});if(r.ok())throw Error('Cross-store identity leak');console.log('CROSS-STORE LOGIN REJECTED',r.status());
const readEnv=p=>Object.fromEntries(fs.readFileSync(p,'utf8').split(/\r?\n/).filter(l=>l.includes('=')).map(l=>{const at=l.indexOf('=');return [l.slice(0,at),l.slice(at+1)]}));const a=readEnv('S:/dracula-design/.env'),d=readEnv('S:/dracula-food/.env');for(const key of ['POSTGRES_PASSWORD','EVA_STOREFRONT_DB_PASSWORD','EVA_ADMIN_DB_PASSWORD','JWT_SECRET','SECRET_KEY'])if(a[key]===d[key])throw Error('Shared secret '+key);console.log('SEPARATE DATABASE/AUTH SECRETS VERIFIED');await b.close();})();
